package com.molirain.molisync.data.cloud

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.LruCache
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import java.io.File
import java.util.concurrent.ConcurrentHashMap

/**
 * Loads image previews from the server, caching decoded bitmaps in memory and
 * the encoded previews on disk. Previews are small JPEGs generated by the
 * server, so browsing a gallery never downloads the original files.
 */
class ThumbnailLoader(
    private val directory: File,
    private val fetch: suspend (recordId: String) -> ByteArray?,
) {
    private val memory = object : LruCache<String, Bitmap>(MEMORY_BUDGET_BYTES) {
        override fun sizeOf(key: String, value: Bitmap): Int = value.byteCount
    }
    private val locks = ConcurrentHashMap<String, Mutex>()

    /** Returns a decoded preview, or null when the record cannot be previewed. */
    suspend fun load(recordId: String): Bitmap? {
        if (recordId.isEmpty()) {
            return null
        }
        memory.get(recordId)?.let { return it }

        if (locks.size > MAX_LOCKS) {
            locks.clear()
        }
        val lock = locks.getOrPut(recordId) { Mutex() }
        return lock.withLock {
            memory.get(recordId) ?: withContext(Dispatchers.IO) {
                decode(recordId)?.also { memory.put(recordId, it) }
            }
        }
    }

    /** Drops every cached preview for a record, e.g. after it is deleted. */
    suspend fun invalidate(recordId: String) = withContext(Dispatchers.IO) {
        memory.remove(recordId)
        previewFile(recordId).delete()
        Unit
    }

    private suspend fun decode(recordId: String): Bitmap? {
        if (!directory.exists() && !directory.mkdirs()) {
            return null
        }
        val file = previewFile(recordId)
        val bytes = if (file.isFile && file.length() > 0) {
            runCatching { file.readBytes() }.getOrNull()
        } else {
            val downloaded = fetch(recordId) ?: return null
            if (downloaded.isEmpty() || downloaded.size > MAX_PREVIEW_BYTES) {
                return null
            }
            runCatching { writeAtomically(file, downloaded) }
            downloaded
        }
        return bytes?.let { decodeBitmap(it) }
    }

    private fun writeAtomically(target: File, bytes: ByteArray) {
        val temporary = File(target.parentFile, target.name + ".part")
        temporary.writeBytes(bytes)
        if (!temporary.renameTo(target)) {
            temporary.copyTo(target, overwrite = true)
            temporary.delete()
        }
    }

    private fun previewFile(recordId: String): File = File(directory, thumbnailFileName(recordId))

    private fun decodeBitmap(bytes: ByteArray): Bitmap? {
        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size, bounds)
        if (bounds.outWidth <= 0 || bounds.outHeight <= 0) {
            return null
        }
        val options = BitmapFactory.Options().apply {
            inSampleSize = sampleSize(bounds.outWidth, bounds.outHeight, TARGET_PIXELS)
        }
        return runCatching {
            BitmapFactory.decodeByteArray(bytes, 0, bytes.size, options)
        }.getOrNull()
    }

    private companion object {
        const val MEMORY_BUDGET_BYTES = 24 * 1024 * 1024
        const val MAX_PREVIEW_BYTES = 4 * 1024 * 1024
        const val TARGET_PIXELS = 640 * 640
        const val MAX_LOCKS = 512
    }
}

/** Cache file name for a record; the record id is validated server-side. */
internal fun thumbnailFileName(recordId: String): String =
    recordId.filter { it.isLetterOrDigit() || it == '-' || it == '_' } + ".jpg"

/**
 * Power-of-two sampling factor that keeps a decoded preview within
 * [targetPixels] while never upscaling.
 */
internal fun sampleSize(width: Int, height: Int, targetPixels: Int): Int {
    if (width <= 0 || height <= 0 || targetPixels <= 0) {
        return 1
    }
    var sample = 1
    while ((width / (sample * 2)) * (height / (sample * 2)) >= targetPixels) {
        sample *= 2
    }
    return sample
}
